mapper.select:
SELECT DISTINCT m.id,m.name,m.icon,m.is_link,m.url,m.type,m.`status`,m.sort_by,m.parent_id FROM `sys_menu` m left join sys_menu_role mr on m.id=mr.menu_id left join sys_role r on r.id=mr.role_id left join sys_user_role ur on ur.role_id=r.id
and ur.user_id=#{userId}
and m.parent_id=#{parentId}
and m.parent_id is null
and m.status='1' and m.type='1'
order by m.sort_by asc

select DISTINCT sm.id,sm.name,sm.type,sm.permission_identity,sm.parent_id
from sys_menu sm left JOIN sys_menu_role smr on smr.menu_id=sm.id left join sys_role sr on sr.id=smr.role_id left join sys_user_role sur on sur.role_id=sr.id
and sur.user_id=#{userId}
and sm.parent_id=#{menuId}
and sm.status='1' and sm.type='2'
